def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1]), fmt([1, 2]), fmt([1, 2, 3]), fmt([3, 1, 4, 2]), fmt([5, 5, 5, 5]), fmt([1, 3, 2]), fmt([2, 3, 1]),
             fmt([-10**9, 10**9, 0]), fmt([1, 0, 1, -4, -3]), fmt([3, 5, 0, 3, 4]), fmt([1, 4, 4, 2, 3])]
    for n in (3, 4, 5, 6, 8, 10, 14, 20):
        for _ in range(3):
            hi = rng.choice([3, 6, 20, 1000])
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)]))
    for n in (30, 40):
        tests.append(fmt(list(range(n, 0, -1))))
        tests.append(fmt(list(range(n))))
    N = 200000
    tests.append(fmt(list(range(N, 0, -1))))
    tests.append(fmt(list(range(-N // 2, N // 2))))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt(list(range(10**9 - N + 1, 10**9 + 1)) + [10**9 - N + 3, 5]))
    tests.append(fmt([10**9 - i for i in range(N)]))
    return tests

